int counter = 0;

// RHS only executes if LHS is true
bool side_effect_fn() { counter = 1; return true; }

// Compiled Structure Analogy:
// if (!LHS) goto skip_rhs;
// if (!RHS) goto fail;
// success;
// skip_rhs: fail:

bool LHS_False() { return false; }

bool skipped = LHS_False() && side_effect_fn();
// counter == 0 (RHS was short-circuited/skipped)

bool LHS_True() { return true; }

bool full_eval = LHS_True() && side_effect_fn();
// counter == 1 (RHS was executed)
